/**
  ******************************************************************************
  * @file    bsp_timer.h
  * @brief   Software-timer / runtime-counter header.
  *
  * @note    Ported from the original Ai-SG01 bsp_timer.h. In this port the 1 ms
  *          tick that drives the soft timers and g_iRunTime is generated by a
  *          hardware TIM (TIM3) instead of SysTick, because SysTick is owned by
  *          FreeRTOS. The public API is identical to the original.
  ******************************************************************************
  */

#ifndef __BSP_TIMER_H
#define __BSP_TIMER_H

/*
	在此定义可用的软件定时器个数（定时器ID范围 0 - TMR_COUNT-1）
*/
#define TMR_COUNT	4		/* 软件定时器的个数, 8个 */

/* 定时器结构, 成员都是 volatile, 防止C编译器优化 */
typedef enum
{
	TMR_ONCE_MODE = 0,		/* 一次工作模式 */
	TMR_AUTO_MODE = 1		/* 自动定时工作模式 */
}TMR_MODE_E;

/* 定时器结构, 成员都是 volatile, 防止C编译器优化 */
typedef struct
{
	volatile uint8_t Mode;		/* 工作模式, 1=单次, 0=自动 */
	volatile uint8_t Flag;		/* 定时到达标志  */
	volatile uint32_t Count;	/* 计数器 */
	volatile uint32_t PreLoad;	/* 预装值 */
}SOFT_TMR;

/* 提供给C文件里使用的函数 */
void bsp_InitTimer(void);
void bsp_DelayMS(uint32_t n);
void bsp_DelayUS(uint32_t n);
void bsp_StartTimer(uint8_t _id, uint32_t _period);
void bsp_StartAutoTimer(uint8_t _id, uint32_t _period);
void bsp_StopTimer(uint8_t _id);
uint8_t bsp_CheckTimer(uint8_t _id);
int32_t bsp_GetRunTime(void);
int32_t bsp_CheckRunTime(int32_t _LastTime);

#endif

